package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsGrand decimal.Decimal = decimal.New(0, 0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var orderLines []string
var orderIdx int
var atEnd bool

func main() {
	// OPEN INPUT ORDER-FILE
	f, err := os.Open("input.dat")
	if err == nil {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			// Remove trailing \r if any (COBOL LINE SEQUENTIAL)
			line = strings.TrimSuffix(line, "\r")
			orderLines = append(orderLines, line)
		}
		f.Close()
	} else {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	orderIdx = 0

	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE ORDER-FILE (no action needed)
	SUMMARY_PARA()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	if orderIdx >= len(orderLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderLines[orderIdx]
	orderIdx++
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse
	orId := line[0:5]
	orStat := line[5:6]
	orQtyStr := line[6:9]
	orPriceStr := line[9:15]

	var qty int64
	s := strings.TrimSpace(orQtyStr)
	if s != "" {
		var v int64
		fmt.Sscanf(s, "%d", &v)
		qty = v
	} else {
		// if all spaces, treat as 0
		qty = 0
	}
	// price: digits only, implied V99
	price := parseImplied(orPriceStr, 2)

	orderRec.OrId = orId
	orderRec.OrStat = orStat
	orderRec.OrQty = qty
	orderRec.OrPrice = price
}

func parseImplied(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// s should be digits, may contain spaces? per COBOL it's digits
	// extract digits
	var digits strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits.WriteRune(ch)
		}
	}
	ds := digits.String()
	if ds == "" {
		return decimal.New(0, 0)
	}
	// parse as integer
	n := decimal.RequireFromString(ds)
	// shift decimal
	n = n.Shift(-scale)
	return n
}

func fitToPic(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order digits that fit: total digits = intDigits+scale (in smallest unit)
	// compute v in smallest unit as integer truncated toward zero at scale
	// v is already at desired scale (rounded/truncated)
	// totalMod = 10^(intDigits+scale)
	totalDigits := intDigits + int(scale)
	mod := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	// factor = 10^scale
	factor := decimal.New(1, scale)
	// get scaled integer (cents) truncated toward zero
	scaled := v.Mul(factor).Truncate(0)
	// For negative values, COBOL keeps sign and drops high order magnitude
	// Use modulus on absolute value then reapply sign
	sign := int32(1)
	if scaled.IsNegative() {
		sign = -1
		scaled = scaled.Abs()
	}
	// low order
	low := scaled.Mod(mod)
	if sign == -1 {
		low = low.Neg()
	}
	result := low.Div(factor)
	return result
}

func PROCESS_PARA() {
	WsTotal = decimal.New(0, 0)
	// EVALUATE TRUE
	if orderRec.OrQty == 0 {
		WsBadQty++
		// DISPLAY OR-ID " BAD QTY"
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		qtyDec := decimal.New(orderRec.OrQty, 0)
		prod := qtyDec.Mul(orderRec.OrPrice)
		// truncated to scale 2
		prod = prod.Truncate(2)
		prod = fitToPic(prod, 8, 2)
		WsTotal = prod
		WsNewCount++
		SHOW_PARA()
	} else if orderRec.OrStat == "S" {
		qtyDec := decimal.New(orderRec.OrQty, 0)
		prod := qtyDec.Mul(orderRec.OrPrice)
		prod = prod.Mul(decimal.RequireFromString("1.05"))
		prod = prod.Round(2)
		prod = fitToPic(prod, 8, 2)
		WsTotal = prod
		WsShipCount++
		SHOW_PARA()
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		SHOW_PARA()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = fitToPic(WsGrand, 10, 2)
	READ_PARA()
}

func SHOW_PARA() {
	WsQtyEd = formatEditedSimple(WsQtyDecimal(), "ZZ9", 0)
	WsPriceEd = formatEditedSimple(orderRec.OrPrice, "Z,ZZ9.99", 2)
	WsTotalEd = formatEditedSimple(WsTotal, "ZZ,ZZZ,ZZ9.99", 2)
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func WsQtyDecimal() decimal.Decimal {
	return decimal.New(orderRec.OrQty, 0)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEditedSimple(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99", 2)
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	fmt.Printf("NEW: %02d SHIPPED: %02d CANCELLED: %02d\n", WsNewCount, WsShipCount, WsCancelCount)
	fmt.Printf("INVALID: %02d BAD QTY: %02d\n", WsInvalid, WsBadQty)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

// formatEditedSimple formats a decimal value according to a COBOL numeric-edited picture
// picture like "ZZ9", "Z,ZZ9.99" etc. dec is number of decimal places implied by picture (count after '.')
func formatEditedSimple(v decimal.Decimal, picture string, dec int) string {
	// split picture into integer part and decimal part
	intPic := picture
	decPic := ""
	if idx := strings.Index(picture, "."); idx >= 0 {
		intPic = picture[:idx]
		decPic = picture[idx+1:]
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// ensure v is at correct scale (truncate/round already done) but we need fractional digits
	// get integer part absolute (for formatting, sign not expected here; all positive)
	// Handle negative: COBOL would show sign? Not needed for this program.
	neg := v.IsNegative()
	if neg {
		v = v.Abs()
	}
	// Extract integer and fractional
	// Use Pow for integer part
	// Get integer part as integer value truncated
	intPart := v.Truncate(0).Abs()
	// fractional part
	// To get dec digits, we can get v with scale dec
	// Compute fractional string with dec digits zero padded
	fracStr := ""
	if dec > 0 {
		// get fractional part: (v - intPart) * 10^dec
		factor := decimal.New(1, int32(dec))
		fracDec := v.Sub(intPart).Mul(factor).Truncate(0).Abs()
		// Need to handle rounding issues where frac due to decimal representation may be off
		// Use IntPart
		fracInt := fracDec.IntPart()
		fracStr = fmt.Sprintf("%0*d", dec, fracInt)
		// overflow handling for integer digits: low-order digits
		// Apply overflow truncation to integer part (keep low-order intDigits)
		// Compute intPart mod 10^intDigits
		if len(intPart.StringFixed(0)) > intDigits {
			// Use decimal mod
			mod := decimal.New(1, int32(intDigits))
			intPart = intPart.Mod(mod)
		}
	} else {
		if len(intPart.StringFixed(0)) > intDigits {
			mod := decimal.New(1, int32(intDigits))
			intPart = intPart.Mod(mod)
		}
	}

	intStrRaw := intPart.StringFixed(0) // without sign, without decimals
	// Remove possible minus
	intStrRaw = strings.TrimPrefix(intStrRaw, "-")
	// Pad with leading zeros to intDigits
	if len(intStrRaw) < intDigits {
		intStrRaw = strings.Repeat("0", intDigits-len(intStrRaw)) + intStrRaw
	} else if len(intStrRaw) > intDigits {
		// low-order already handled, but if still longer (should not), take last intDigits
		intStrRaw = intStrRaw[len(intStrRaw)-intDigits:]
	}
	// Now format integer part according to intPic
	// Walk intPic left to right, consuming digits from intStrRaw
	var outInt strings.Builder
	digitIdx := 0
	suppressing := true
	// Need to know if remaining placeholders include a '9' to determine final zero display
	// The algorithm: for each placeholder Z/9, decide
	for _, ch := range intPic {
		switch ch {
		case 'Z', '9':
			d := intStrRaw[digitIdx]
			digitIdx++
			if ch == 'Z' {
				if suppressing && d == '0' {
					// Check if this is the last digit placeholder and all digits are zero?
					// For Z, suppressed to space; suppression continues
					outInt.WriteByte(' ')
				} else {
					suppressing = false
					outInt.WriteByte(d)
				}
			} else { // '9'
				suppressing = false
				outInt.WriteByte(d)
			}
		case ',':
			if suppressing {
				outInt.WriteByte(' ')
			} else {
				outInt.WriteByte(',')
			}
		default:
			outInt.WriteRune(ch)
		}
	}
	result := outInt.String()
	if dec > 0 {
		result = result + "." + fracStr
	}
	if neg {
		// COBOL would place sign; not needed for tests
		result = "-" + result
	}
	return result
}

